'use strict';
const $=id=>document.getElementById(id),root=document.querySelector('.rocket-game');let current={state:'idle',balance:0},connected=false,pending=false,returnAfter=false,lastState='',lastRound='';const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');
function send(type){if(window.parent!==window)window.parent.postMessage({type},location.origin)}
function render(d){current=d;connected=true;pending=false;root.className='rocket-game '+d.state;$('balance').textContent=d.balance.toLocaleString();$('multiplier').innerHTML=d.multiplier.toFixed(2)+'<span>×</span>';$('payout').textContent=d.state==='idle'?'—':d.payout+' 积分';const flying=d.state==='flying',crashed=d.state==='crashed',collected=d.state==='collected';$('status').textContent=flying?'飞行中 · 随时收取':crashed?'火箭坠毁':collected?'已安全收取':'准备发射';$('flight-time').textContent=d.state==='idle'?'飞得越久，收取得分越高':'本次飞行 '+d.elapsed.toFixed(1)+' 秒';$('action').disabled=!flying&&d.balance<50;$('action').textContent=flying?'立即收取 · '+d.payout+' 积分':d.balance<50?'积分不足 · 去扫雷赚积分':d.state==='idle'?'发射火箭 · 50 积分':'再飞一次 · 50 积分';
 if(lastState!==d.state||lastRound!==d.roundId){$('message').textContent=flying?'奖励还未入账，坠毁前点击「立即收取」。':crashed?'本局未收取奖励归零，已消耗的 50 积分不退还。':collected?'已到账 '+d.payout+' 积分，本局净得 '+(d.payout-50)+' 积分。':'每次发射消耗 50 积分；坠毁前主动收取。';lastState=d.state;lastRound=d.roundId;}
 const x=22+54*(1-Math.exp(-d.elapsed/8)),y=81-26*(1-Math.exp(-d.elapsed/9));$('rocket').style.left=(reduce.matches?55:x)+'%';$('rocket').style.top=(reduce.matches?66:y)+'%';$('burst').style.left=x+'%';$('burst').style.top=y+'%';$('route').setAttribute('d',`M 220 486 Q 420 486 ${x*10} ${y*6}`);if(returnAfter&&d.state!=='flying'){returnAfter=false;send('game-return')}
}
window.addEventListener('message',e=>{if(e.source!==window.parent||e.origin!==location.origin||!e.data)return;if(e.data.type==='rocket-state')render(e.data);if(e.data.type==='rocket-error'){pending=false;$('message').textContent=e.data.message;$('action').disabled=false}});
$('action').onclick=()=>{if(!connected||pending)return;pending=true;$('action').disabled=true;send(current.state==='flying'?'rocket-collect':'rocket-launch')};
function modal(title,text,actions){$('dialog-title').textContent=title;$('dialog-text').textContent=text;$('dialog-actions').replaceChildren();for(const [label,fn] of actions){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{$('dialog').close();fn()};$('dialog-actions').append(b)}$('dialog').showModal()}
$('rules').onclick=()=>modal('小火箭怎么玩？','每局消耗 50 模拟积分，起飞后倍率持续增长。\n随时点击收取，到账积分 = 50 × 当前倍率（向下取整，含本局投入）。\n火箭会在随机时刻坠毁；如果尚未收取，本局奖励为 0，发射积分不退还。\n切出页面或打开说明不会暂停飞行。',[['知道了',()=>{}]]);
$('back').onclick=()=>{if(current.state==='flying')modal('飞行仍在继续','返回大厅不会暂停火箭。你可以先收取当前积分，再返回。',[['收取并返回',()=>{returnAfter=true;send('rocket-collect')}],['继续看火箭',()=>{}],['直接返回大厅',()=>send('game-return')]]);else send('game-return')};
for(let i=0;i<35;i++){const s=document.createElement('i');s.className='star';s.style.left=((i*37)%100)+'%';s.style.top=((i*61)%100)+'%';s.style.opacity=.15+(i%4)*.12;$('stars').append(s)}
if(window.parent===window){$('message').textContent='请从 PLAYROOM 大厅打开小火箭。';$('action').textContent='返回游戏大厅';$('action').disabled=false;$('action').onclick=()=>location.href='./'}else send('rocket-ready');
